head.script:
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    var wSrc = "tabControl_fwGauge_WPFF-349_(WSQ-3884)_sub.xml";
    var tabOpt = {
        label: "test_" + cnt,
        closable: true,
        openAction: "exist"
    };
    var contOpt = {
        src: wSrc,
        title: "wframe title",
        frameMode: "wframe",
        alwaysDraw: true
    };
    tabControl1.addTab("test_" + cnt, tabOpt, contOpt);
    cnt++;
};
scwin.checkVal = function() {
    return WebSquare.wUnit.getDomById('raphael-paper-0') != null;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('tabControl1_tab_test_0').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload = function() {

    window.cnt = 0;
	scwin.unitTest();
}
